17	// The primary key for the ModelConfig is the model string. However, we also
18	// support a secondary key to limit the override scope, typically an agent name.
19	export interface ModelConfigKey {
20	  model: string;
21	
22	  // In many cases the model (or model config alias) is sufficient to fully
23	  // scope an override. However, in some cases, we want additional scoping of
24	  // an override. Consider the case of developing a new subagent, perhaps we
25	  // want to override the temperature for all model calls made by this subagent.
26	  // However, we most certainly do not want to change the temperature for other
27	  // subagents, nor do we want to introduce a whole new set of aliases just for
28	  // the new subagent. Using the `overrideScope` we can limit our overrides to
29	  // model calls made by this specific subagent, and no others, while still
30	  // ensuring model configs are fully orthogonal to the agents who use them.
31	  overrideScope?: string;
32	
33	  // Indicates whether this configuration request is happening during a retry attempt.
34	  // This allows overrides to specify different settings (e.g., higher temperature)
35	  // specifically for retry scenarios.
36	  isRetry?: boolean;
37	
38	  // Indicates whether this request originates from the primary interactive chat model.
39	  // Enables the default fallback configuration to `chat-base` when unknown.
40	  isChatModel?: boolean;
41	}
