62	// A model definition is a mapping from a model name to a list of features
63	// that the model supports. Model names can be either direct model IDs
64	// (gemini-2.5-pro) or aliases (auto).
65	export interface ModelDefinition {
66	  displayName?: string;
67	  tier?: string; // 'pro' | 'flash' | 'flash-lite' | 'custom' | 'auto'
68	  family?: string; // The gemini family, e.g. 'gemini-3' | 'gemini-2'
69	  isPreview?: boolean;
70	  // Specifies whether the model should be visible in the dialog.
71	  isVisible?: boolean;
72	  /** A short description of the model for the dialog. */
73	  dialogDescription?: string;
74	  features?: {
75	    // Whether the model supports thinking.
76	    thinking?: boolean;
77	    // Whether the model supports mutlimodal function responses. This is
78	    // supported in Gemini 3.
79	    multimodalToolUse?: boolean;
80	  };
81	}
82	
83	// A model resolution is a mapping from a model name to a list of conditions
84	// that can be used to resolve the model to a model ID.
85	export interface ModelResolution {
86	  // The default model ID to use when no conditions are met.
87	  default: string;
88	  // A list of conditions that can be used to resolve the model.
89	  contexts?: Array<{
90	    // The condition to check for.
91	    condition: ResolutionCondition;
92	    // The model ID to use when the condition is met.
93	    target: string;
94	  }>;
95	}
