7	import type { Config } from '../config/config.js';
8	import {
9	  openBrowserSecurely,
10	  shouldLaunchBrowser,
11	} from '../utils/secure-browser-launcher.js';
12	import { debugLogger } from '../utils/debugLogger.js';
13	import { getErrorMessage } from '../utils/errors.js';
14	import type { FallbackIntent, FallbackRecommendation } from './types.js';
15	import { classifyFailureKind } from '../availability/errorClassification.js';
16	import {
17	  buildFallbackPolicyContext,
18	  resolvePolicyChain,
19	  resolvePolicyAction,
20	  applyAvailabilityTransition,
21	} from '../availability/policyHelpers.js';
22	
23	export const UPGRADE_URL_PAGE = 'https://goo.gle/set-up-gemini-code-assist';
24	
25	export async function handleFallback(
26	  config: Config,
27	  failedModel: string,
28	  authType?: string,
29	  error?: unknown,
30	): Promise<string | boolean | null> {
31	  const failureKind = classifyFailureKind(error);
32	
33	  const chain = resolvePolicyChain(config);
34	  const { failedPolicy, candidates } = buildFallbackPolicyContext(
35	    chain,
36	    failedModel,
37	  );
38	
39	  const availability = config.getModelAvailabilityService();
40	  const getAvailabilityContext = () => {
41	    if (!failedPolicy) return undefined;
42	    return { service: availability, policy: failedPolicy };
43	  };
44	
45	  let fallbackModel: string;
46	  if (!candidates.length) {
47	    fallbackModel = failedModel;
48	  } else {
49	    const selection = availability.selectFirstAvailable(
50	      candidates.map((policy) => policy.model),
51	    );
52	
53	    const lastResortPolicy = candidates.find((policy) => policy.isLastResort);
54	    const selectedFallbackModel =
55	      selection.selectedModel ?? lastResortPolicy?.model;
56	    const selectedPolicy = candidates.find(
57	      (policy) => policy.model === selectedFallbackModel,
58	    );
59	
60	    if (
61	      !selectedFallbackModel ||
62	      selectedFallbackModel === failedModel ||
63	      !selectedPolicy
64	    ) {
65	      return null;
66	    }
67	
68	    fallbackModel = selectedFallbackModel;
69	
70	    // failureKind is already declared and calculated above
71	    const action = resolvePolicyAction(failureKind, selectedPolicy);
72	
73	    if (action === 'silent') {
74	      applyAvailabilityTransition(getAvailabilityContext, failureKind);
75	      return processIntent(config, 'retry_always', fallbackModel);
76	    }
77	
78	    // This will be used in the future when FallbackRecommendation is passed through UI
79	    const recommendation: FallbackRecommendation = {
80	      ...selection,
81	      selectedModel: fallbackModel,
82	      action,
83	      failureKind,
84	      failedPolicy,
85	      selectedPolicy,
86	    };
87	    void recommendation;
88	  }
89	
90	  const handler = config.getFallbackModelHandler();
91	  if (typeof handler !== 'function') {
92	    return null;
93	  }
94	
95	  try {
96	    const intent = await handler(failedModel, fallbackModel, error);
97	
98	    // If the user chose to switch/retry, we apply the availability transition
99	    // to the failed model (e.g. marking it terminal if it had a quota error).
100	    // We DO NOT apply it if the user chose 'stop' or 'retry_later', allowing
101	    // them to try again later with the same model state.
102	    if (intent === 'retry_always' || intent === 'retry_once') {
103	      applyAvailabilityTransition(getAvailabilityContext, failureKind);
104	    }
105	
106	    return await processIntent(config, intent, fallbackModel);
107	  } catch (handlerError) {
108	    debugLogger.error('Fallback handler failed:', handlerError);
109	    return null;
110	  }
111	}
112	
113	async function handleUpgrade() {
114	  if (!shouldLaunchBrowser()) {
115	    debugLogger.log(
116	      `Cannot open browser in this environment. Please visit: ${UPGRADE_URL_PAGE}`,
117	    );
118	    return;
119	  }
120	  try {
121	    await openBrowserSecurely(UPGRADE_URL_PAGE);
122	  } catch (error) {
123	    debugLogger.warn(
124	      'Failed to open browser automatically:',
125	      getErrorMessage(error),
126	    );
127	  }
128	}
129	
130	async function processIntent(
131	  config: Config,
132	  intent: FallbackIntent | null,
133	  fallbackModel: string,
134	): Promise<boolean> {
135	  switch (intent) {
136	    case 'retry_always':
137	      // TODO(telemetry): Implement generic fallback event logging. Existing
138	      // logFlashFallback is specific to a single Model.
139	      config.activateFallbackMode(fallbackModel);
140	      return true;
141	
142	    case 'retry_once':
143	      // For distinct retry (retry_once), we do NOT set the active model permanently.
144	      // The FallbackStrategy will handle routing to the available model for this turn
145	      // based on the availability service state (which is updated before this).
146	      return true;
147	
148	    case 'retry_with_credits':
149	      return true;
150	
151	    case 'stop':
152	      // Do not switch model on stop. User wants to stay on current model (and stop).
153	      return false;
154	
155	    case 'retry_later':
156	      return false;
157	
158	    case 'upgrade':
159	      await handleUpgrade();
160	      return false;
161	
162	    default:
163	      throw new Error(
164	        `Unexpected fallback intent received from fallbackModelHandler: "${intent}"`,
165	      );
166	  }
167	}
